def getSuitVitals(name, level = -1):
    data = SuitAttributes[name]
    if level == -1:
        level = pickFromFreqList(data['freq'])
    dict = {}
    dict['level'] = getActualFromRelativeLevel(name, level)
    if dict['level'] == 11:
        level = 0
    dict['hp'] = data['hp'][level]
    dict['def'] = data['def'][level]
    attacks = data['attacks']
    cheats = data['cheats']
    alist = []
    clist = []
    for a in attacks:
        adict = {}
        name = a[0]
        adict['name'] = name
        adict['animName'] = SuitAttacks[name][0]
        # Try and get the attack data from the appropriate index.
        try:
            adict['hp'] = a[1][level]
        except IndexError:
            # Chances are we went over.  Let's do overleveling logic!
            adict['hp'] = a[1][len(a[1]) - 1] + (level - (len(a[1]) - 1))
        # Same thing for the below, except we're just using the final index rather than adding anything to the final index.
        try:
            adict['acc'] = a[2][level]
        except IndexError:
            adict['acc'] = a[2][len(a[2]) - 1]
        try:
            adict['freq'] = a[3][level]
        except:
            adict['freq'] = a[3][len(a[3]) - 1]
        # Attack tuples have four indices.  This will check to see if there is a fifth one, which I would like to use to make single-target attacks able to be used as group, provided we have a method for its use.
        if len(a) > 4:
            adict['group'] = a[4]
        else:
            # Use the default targeting in SuitAttacks.
            adict['group'] = SuitAttacks[name][1]
        alist.append(adict)
    for c in cheats:
        cdict = {}
        name = c[0]
        cdict['name'] = name
        cdict['animName'] = SuitCheats[name][0]
        cdict['hp'] = c[1][level]
        cdict['acc'] = c[2][level]
        cdict['freq'] = c[3][level]
        cdict['group'] = SuitCheats[name][1]
        clist.append(cdict)

    dict['attacks'] = alist
    dict['cheats'] = clist
    return dict


def calculateDefense(suitLevel, levelOffset, boost=0):
    defense = int(suitLevel * 5 + (levelOffset * 5))
    if defense > 55:
        defense = 55
    elif defense <= 0:
        defense = 2
    defense += boost
    return defense

def getAttackIndex(attackName, suitName):
    '''
    For convenience, until I find a way to use attack names instead of indexes for SUIT_ATK_COL, grab the index based on the attack name.
    attackName: The attack (e.g. 'ClipOnTie', 'SnapWet', etc.).
    '''
    attacks = SuitAttributes[suitName]['attacks']
    for i in xrange(len(attacks)):
        attack = attacks[i]
        if isinstance(attack, SuitAttack):
            if attack.name == attackName:
                return i
        else:
            if attack[0] == attackName:
                return i

    # No attack found.
    notify.warning('Did not find attack %s for suitName %s' % (attackName, suitName))
    return -1

def pickSuitAttack(attacks, suitLevel):
    attackNum = None
    randNum = random.randint(0, 99)
    notify.debug('pickSuitAttack: rolled %d' % randNum)
    count = 0
    index = 0
    total = 0
    for c in attacks:
        total = total + c[3][suitLevel]

    for c in attacks:
        count = count + c[3][suitLevel]
        if randNum < count:
            attackNum = index
            notify.debug('picking attack %d' % attackNum)
            break
        index = index + 1

    configAttackName = simbase.config.GetString('attack-type', 'random')
    if configAttackName == 'random':
        return attackNum
    elif configAttackName == 'sequence':
        for i in xrange(len(attacks)):
            if  attacks[i] not in debugAttackSequence:
                debugAttackSequence[attacks[i]] = 1
                return i

        return attackNum
    else:
        for i in xrange(len(attacks)):
            if attacks[i][0] == configAttackName:
                return i

        return attackNum
    return

def pickSuitCheat(cheats, suitLevel):
    cheatNum = None
    randNum = random.randint(0, 99)
    notify.debug('pickSuitAttack: rolled %d' % randNum)
    count = 0
    index = 0
    total = 0
    for c in cheats:
        total = total + c[3][suitLevel]

    for c in cheats:
        count = count + c[3][suitLevel]
        if randNum < count:
            attackNum = index
            notify.debug('picking attack %d' % attackNum)
            break
        index = index + 1

    configAttackName = simbase.config.GetString('attack-type', 'random')
    if configAttackName == 'random':
        return attackNum
    elif configAttackName == 'sequence':
        for i in xrange(len(attacks)):
            if cheats[i] not in debugAttackSequence:
                debugAttackSequence[cheats[i]] = 1
                return i

        return cheatNum
    else:
        for i in xrange(len(cheats)):
            if cheats[i][0] == configAttackName:
                return i

        return cheatNum
    return

def getSuitCheat(suitName, suitLevel, cheatNum = -1):
    cheatChoices = SuitAttributes[suitName]['cheats']
    if cheatNum == -1:
        notify.debug('getSuitAttack: picking attacking for %s' % suitName)
        cheatNum = pickSuitCheat(cheatChoices, suitLevel)
    cheat = cheatChoices[cheatNum]
    cdict = {}
    cdict['suitName'] = suitName
    name = attack[0]
    cdict['name'] = name
    cdict['id'] = SuitAttacks.keys().index(name)
    cdict['animName'] = SuitAttacks[name][0]
    cdict['hp'] = cheat[1][suitLevel]
    cdict['acc'] = cheat[2][suitLevel]
    cdict['freq'] = cheat[3][suitLevel]
    cdict['group'] = SuitAttacks[name][1]
    return cdict


def getSuitAttack(suitName, suitLevel, attackNum = -1):
    attackChoices = SuitAttributes[suitName]['attacks']
    if attackNum == -1:
        notify.debug('getSuitAttack: picking attacking for %s' % suitName)
        attackNum = pickSuitAttack(attackChoices, suitLevel)
    attack = attackChoices[attackNum]
    adict = {}
    adict['suitName'] = suitName
    name = attack[0]
    adict['name'] = name
    adict['id'] = SuitAttacks.keys().index(name)
    adict['animName'] = SuitAttacks[name][0]
    adict['hp'] = attack[1][suitLevel]
    adict['acc'] = attack[2][suitLevel]
    adict['freq'] = attack[3][suitLevel]
    if len(attack) > 4:
        adict['group'] = attack[4]
    else:
        adict['group'] = SuitAttacks[name][1]
    return adict

